//! Casks retain the complete source-bound package in Homebrew's Caskroom.

use super::binary;
use crate::util;
use anyhow::{Context, Result, ensure};
use serde_json::{Value, json};
use std::path::Path;

pub fn generate(archive: &Path, output: &Path) -> Result<Value> {
    let verified = binary::verify(archive, None)?;
    ensure!(
        verified["release_ready"] == true
            && verified["target"] == "aarch64-apple-darwin"
            && verified["package"]["name"] == "lazypencil",
        "Homebrew distribution requires a verified supported stable release"
    );
    let version = verified["package"]["version"]
        .as_str()
        .context("Missing package version")?;
    let minimum_os = verified["release"]["minimum_os"]
        .as_str()
        .context("Missing minimum macOS version")?;
    let checksum = verified["sha256"].as_str().context("Missing checksum")?;
    // Only numeric stable versions may enter the Ruby DSL or download URL.
    ensure!(
        regex::Regex::new(r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$")?
            .is_match(version),
        "Homebrew distribution requires a numeric stable version"
    );
    // Support recent macOS generations without patch-specific install hooks.
    // Keep the named Homebrew dependency aligned with the source declaration.
    ensure!(
        minimum_os == "26.0.0",
        "Update the named Homebrew dependency when changing the supported macOS generation"
    );
    let cask = format!(
        r#"# Generated by lazypencil's release workflow. Do not edit manually.
cask "lazypencil" do
  version "{version}"
  sha256 "{checksum}"

  url "https://github.com/EkeMinusYou/lazypencil/releases/download/v#{{version}}/lazypencil-#{{version}}-aarch64-apple-darwin.tar.gz"
  name "lazypencil"
  desc "Terminal-first .pen design editor, renderer, and MCP server"
  homepage "https://github.com/EkeMinusYou/lazypencil"

  livecheck do
    skip "Updated by the signed release workflow."
  end

  depends_on arch: :arm64
  depends_on macos: :tahoe

  binary "lazypencil-#{{version}}-aarch64-apple-darwin/bin/lazypencil"
end
"#
    );
    util::publish(output, cask.as_bytes(), false)?;
    Ok(
        json!({"version":version,"sha256":checksum,"cask":output,"source_revision":verified["source_revision"]}),
    )
}
